WITH scored AS (SELECT *, LAG(sqft, 2, 0) OVER (PARTITION BY region ORDER BY opened_date, id) AS prev_sqft, COUNT(sqft) OVER (PARTITION BY region) AS region_count_sqft FROM stores), scored_stores AS (SELECT id, store_name, region, sqft, prev_sqft, region_count_sqft, FIRST_VALUE(region_count_sqft) IGNORE NULLS OVER (PARTITION BY YEAR(opened_date) ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region_count_sqft, LEAD(sqft, 1) OVER (PARTITION BY region, city ORDER BY region_count_sqft, id) AS next_sqft FROM scored), with_windows AS (SELECT *, LAG(first_known_region_count_sqft) OVER (PARTITION BY region ORDER BY prev_sqft, id) AS prev_first_known_region_count_sqft, LEAD(first_known_region_count_sqft) OVER (PARTITION BY region ORDER BY prev_sqft, id) AS next_first_known_region_count_sqft, LAG(sqft) OVER (PARTITION BY region ORDER BY prev_sqft, id) AS prev_sqft_2, LEAD(sqft) OVER (PARTITION BY region ORDER BY prev_sqft, id) AS next_sqft_2, ROW_NUMBER() OVER (PARTITION BY region ORDER BY prev_sqft, id) AS row_seq, RANK() OVER (PARTITION BY region ORDER BY first_known_region_count_sqft DESC NULLS LAST) AS first_known_region_count_sqft_rank FROM scored_stores), metrics AS (SELECT id, sqft, prev_sqft, region_count_sqft, first_known_region_count_sqft, next_first_known_region_count_sqft, prev_sqft_2, next_sqft_2, row_seq, MAX(next_sqft) OVER w_running AS last4_max_next_sqft, MIN(next_sqft) OVER w_running AS last4_min_next_sqft, COUNT(next_sqft) OVER w_running AS last4_count_next_sqft, ROW_NUMBER() OVER (PARTITION BY region ORDER BY next_sqft DESC, id) AS event_seq FROM with_windows WINDOW w_running AS (PARTITION BY region ORDER BY prev_sqft, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), latest_match AS (SELECT s.*, latest.order_discount FROM metrics s LEFT JOIN LATERAL (SELECT c.discount AS order_discount FROM orders c WHERE c.store_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, sqft, prev_sqft, region_count_sqft, first_known_region_count_sqft, next_first_known_region_count_sqft, prev_sqft_2, row_seq, last4_count_next_sqft FROM latest_match ORDER BY last4_count_next_sqft DESC;
